package com.example.techfix.activities;
import android.app.*; import android.content.*; import android.os.*; import android.view.*; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import androidx.lifecycle.*; import androidx.recyclerview.widget.*; import com.example.techfix.R; import com.example.techfix.adapters.RepairJobAdapter; import com.example.techfix.data.*; import java.util.*; import java.util.concurrent.*;
public class RepairHistoryActivity extends AppCompatActivity { private RepairJobAdapter adapter; private TextView empty; public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_repair_history);empty=findViewById(R.id.tvHistoryEmpty);RecyclerView rv=findViewById(R.id.rvRepairHistory);rv.setLayoutManager(new LinearLayoutManager(this));adapter=new RepairJobAdapter(this::showDetails);rv.setAdapter(adapter);RepairViewModel model=new ViewModelProvider(this, ViewModelProvider.AndroidViewModelFactory.getInstance(getApplication())).get(RepairViewModel.class);int userId=getSharedPreferences("TechFixPrefs",MODE_PRIVATE).getInt("userId",-1);model.jobsForUser(userId).observe(this,list->{adapter.submitList(list);empty.setVisibility(list==null||list.isEmpty()?View.VISIBLE:View.GONE);});findViewById(R.id.btnHistoryBack).setOnClickListener(v->finish());}
 private void showDetails(RepairJob j){TechFixDatabase.get(this).repairDao();new Thread(()->{RepairDao dao=TechFixDatabase.get(this).repairDao();Device d=dao.device(j.deviceId);List<Part> parts=dao.parts(j.id);StringBuilder p=new StringBuilder();for(Part x:parts)p.append("\n• ").append(x.name).append(" x").append(x.quantity);runOnUiThread(()->{LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(32,16,32,8);if(j.photoPath!=null){ImageView image=new ImageView(this);image.setImageURI(android.net.Uri.fromFile(new java.io.File(j.photoPath)));image.setAdjustViewBounds(true);box.addView(image);}TextView text=new TextView(this);text.setText("Device: "+(d==null?"":d.model)+"\nIssue: "+j.issueType+"\nStatus: "+j.status+"\nTechnician: "+(j.technicianAssigned==null?"Unassigned":j.technicianAssigned)+"\nParts used:"+(p.length()==0?" none":p));text.setTextColor(getColor(R.color.tech_text_primary));text.setPadding(0,16,0,8);box.addView(text);new AlertDialog.Builder(this).setTitle("Repair details").setView(box).setPositiveButton("Close",null).show();});}).start();}
}
